typedef unsigned int color32;

struct FEMenu;
struct FEMenuSystem {
    char padding[0x74];
    FEMenu **menus;
};

enum { SONGS_PER_SCREEN = 6 };

struct FEMenu {
    char padding0[0x34];
    float scale_high;
    char padding1[0x20];
    FEMenu *back;
    int back_num;
    char padding2[0x18];
    const void *vtable;
};

struct PauseMenuSystem : FEMenuSystem {
    enum { OptionsMenu = 3 };
};

struct stringx;
struct FEMenuEntry;
struct TextString;

struct PlaylistMenuClass {
    FEMenu base;
    PauseMenuSystem *sys;
    stringx *song_names;
    FEMenuEntry *songName[SONGS_PER_SCREEN];
    TextString *upArrow;
    TextString *downArrow;
    TextString *helpText2;
    TextString *lineNumbers[SONGS_PER_SCREEN];
    TextString *onOff[SONGS_PER_SCREEN];
    TextString *playing;
    TextString *currentSong;
    TextString *currentArtist;
    int offset;
    int pos;
    int active;
    int numSongs;
    color32 col;
    color32 colh;
    bool tweaked;
};

extern "C" void FEMenuCtor(FEMenu *self) __asm__("__6FEMenu");
extern "C" void FEMenuCons(
    FEMenu *self, FEMenuSystem *system, int x, int y,
    color32 color, color32 color_high, color32 color_high_alt,
    float scale, float scale_high, int max_visible, int flags)
    __asm__("cons__6FEMenuP12FEMenuSystemiiG7color32N24ffii");
extern "C" void SetHelpText(FEMenu *self, int flags)
    __asm__("SetHelpText__6FEMenui");
extern const char playlist_menu_vtable[];

__asm__(".equ __6FEMenu, 0x00156280");
__asm__(".equ cons__6FEMenuP12FEMenuSystemiiG7color32N24ffii, 0x00156330");
__asm__(".equ SetHelpText__6FEMenui, 0x00156E20");
__asm__(".equ playlist_menu_vtable, 0x004C7AE0");

extern "C" PlaylistMenuClass *PlaylistMenuCtor(
    PlaylistMenuClass *self, FEMenuSystem *system, int x, int y,
    color32 color, color32 color_high, color32 color_high_alt)
    __asm__("__17PlaylistMenuClassP12FEMenuSystemiiG7color32N24");

PlaylistMenuClass *PlaylistMenuCtor(
    PlaylistMenuClass *self, FEMenuSystem *system, int x, int y,
    color32 color, color32 color_high, color32 color_high_alt)
{
    FEMenuCtor(&self->base);
    self->base.vtable = playlist_menu_vtable;

    self->active = 0;
    self->tweaked = false;
    self->col = color;
    self->colh = color_high;
    self->offset = 0;
    self->pos = 0;
    FEMenuCons(&self->base, system, x, y, color, color_high, color_high_alt,
               1.0f, 1.2f, 8, 0);
    self->upArrow = 0;
    self->downArrow = 0;
    self->helpText2 = 0;
    self->playing = 0;
    self->currentSong = 0;
    self->currentArtist = 0;
    for (int i = 0; i < SONGS_PER_SCREEN; i++) {
        self->lineNumbers[i] = 0;
        self->onOff[i] = 0;
    }

    self->sys = (PauseMenuSystem *)system;
    self->base.back = self->sys->menus[PauseMenuSystem::OptionsMenu];
    self->base.back_num = 1;
    SetHelpText(&self->base, 0);
    self->base.scale_high = 1.0f;
    return self;
}
